CultureManagement = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=CultureManagement]");
        api.addToMetaCache([{
            Name: "Core",
            Types: [
                [meta[Core/AppCulture]],
                [meta[Core/Culture]]
            ]
        }]);
        var ds = await model.getDatasource({ endpoint: "ContentManagement/AppCulture", odataAppend: "?$filter=AppId eq " + app.Id + "&$expand=Culture" });
        var cultureGrid = new GridWidget($("[name=cultureGrid]", container), ds);
        cultureGrid.searchable = true;
        cultureGrid.search = { fields: ["CultureId", "Culture.Name"] };
        cultureGrid.groupable = false;
        cultureGrid.filterable = true;
        cultureGrid.columns = [
            { field: "CultureId", title: "[resource_displayname[cultureid]]" },
            { field: "Culture.Name", title: "[resource_displayname[name]]" }
        ];
        cultureGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        cultureGrid.commands.push({ name: "delete", icon: "k-i-trash", text: "[resource_displayname[delete]]" });
        cultureGrid.dataBound = function() {
            $("[name=save]", cultureGrid.gridElement).off("click").on("click", async function(e) {
                e.preventDefault();
                await cultureGrid.dataItem($(e.currentTarget).closest("tr")).save().then(() => notification.success("[resource_displayname[saved]]")).catch((err) => error(err));
            });
            $("[name=delete]", cultureGrid.gridElement).off("click").on("click", async function(e) {
                e.preventDefault();
                var item = cultureGrid.dataItem($(e.currentTarget).closest("tr"));
                await api.destroy("ContentManagement/AppCulture(AppId=" + item.AppId + ",CultureId='" + item.CultureId + "')").then(() => cultureGrid.refresh()).catch((err) => error(err));
            });
        };
        await cultureGrid.init();
    }
};
